const state={transactions:JSON.parse(localStorage.getItem('condo-transactions')||'[]'),properties:JSON.parse(localStorage.getItem('condo-properties')||'[]')};
const byId=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:0}).format(n||0);
byId('today').textContent=new Intl.DateTimeFormat('th-TH',{dateStyle:'full'}).format(new Date());
function save(){localStorage.setItem('condo-transactions',JSON.stringify(state.transactions));localStorage.setItem('condo-properties',JSON.stringify(state.properties));render()}
function render(){const income=state.transactions.filter(x=>x.type==='income').reduce((a,x)=>a+x.amount,0),expense=state.transactions.filter(x=>x.type==='expense').reduce((a,x)=>a+x.amount,0);byId('incomeTotal').textContent=money(income);byId('expenseTotal').textContent=money(expense);byId('netTotal').textContent=money(income-expense);const term=(byId('searchTransactions').value||'').toLowerCase(),type=byId('typeFilter').value;const rows=state.transactions.filter(x=>(!type||x.type===type)&&(`${x.detail} ${x.date}`).toLowerCase().includes(term));byId('transactionRows').innerHTML=rows.length?rows.map(x=>`<tr><td>${x.date}</td><td>${x.type==='income'?'รายรับ':'รายจ่าย'}</td><td>${x.detail}</td><td class="${x.type}">${money(x.amount)}</td><td><span class="status ${x.type==='income'?'blue':'amber'}">ร่าง</span></td></tr>`).join(''):'<tr class="empty-row"><td colspan="5">ยังไม่มีข้อมูล — เพิ่มรายการแรกเพื่อเริ่มต้น</td></tr>';byId('propertyList').innerHTML=state.properties.length?state.properties.map(p=>`<article class="panel"><span class="status blue">ข้อมูลร่าง</span><h3>${p.name}</h3><p>${p.type} · ${p.status}</p><p class="muted">ราคาเช่าที่ยืนยัน: ${p.rent?money(p.rent):'ยังไม่ระบุ'}</p></article>`).join(''):`<article class="empty"><b>⌂</b><h3>ยังไม่มีทรัพย์สินที่ยืนยัน</h3><p>พบป้ายกำกับ A508 และ C424 ในเอกสาร แต่ยังไม่สร้างข้อมูลทรัพย์สินอัตโนมัติ</p><button class="primary" data-open="property">เพิ่มรายการแรก</button></article>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openForm(b.dataset.open));}
function openForm(kind){const modal=byId('modal'),fields=byId('formFields');byId('entryForm').dataset.kind=kind;const isProperty=kind==='property';byId('modalTitle').textContent=isProperty?'เพิ่มทรัพย์สิน':'บันทึก'+(kind==='income'?'รายรับ':'รายจ่าย');fields.innerHTML=isProperty?`<div class="field"><label>ชื่อหรือรหัสทรัพย์สิน</label><input required name="name" placeholder="เช่น A508" /></div><div class="field"><label>ประเภท</label><input name="type" placeholder="เช่น ห้องชุด" /></div><div class="field"><label>สถานะ</label><select name="status"><option>รอตรวจสอบ</option><option>ว่าง</option><option>มีผู้เช่า</option></select></div><div class="field"><label>ค่าเช่าต่อเดือน (บาท)</label><input type="number" min="0" name="rent" /></div>`:`<div class="field"><label>วันที่</label><input required type="date" name="date" value="${new Date().toISOString().slice(0,10)}" /></div><div class="field"><label>รายละเอียด</label><input required name="detail" placeholder="เช่น ค่าเช่าเดือน…" /></div><div class="field"><label>จำนวนเงิน (บาท)</label><input required type="number" min="0" name="amount" /></div><p class="muted">รายการจะถูกบันทึกเป็น “ร่าง” ในอุปกรณ์นี้เท่านั้น</p>`;modal.showModal()}
byId('entryForm').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(e.target.dataset.kind==='property')state.properties.push({...d,rent:+d.rent});else state.transactions.unshift({...d,type:e.target.dataset.kind,amount:+d.amount});e.target.closest('dialog').close();toast('บันทึกร่างแล้ว — โปรดยืนยันก่อนใช้เป็นข้อมูลการเงิน');save()});
document.querySelectorAll('.nav,[data-page-link]').forEach(b=>b.onclick=()=>{const page=b.dataset.page||b.dataset.pageLink;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('visible',x.id===page));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));byId('pageTitle').textContent=page==='dashboard'?'สวัสดีครับ':b.textContent.trim();document.querySelector('.sidebar').classList.remove('open')});
byId('searchTransactions').oninput=render;byId('typeFilter').onchange=render;byId('theme').onclick=()=>document.body.classList.toggle('dark');document.querySelector('.hamburger').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
function toast(t){const x=byId('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3600)}
const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('condo-ledger-local',2);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('documents'))r.result.createObjectStore('documents',{keyPath:'id'});if(!r.result.objectStoreNames.contains('settings'))r.result.createObjectStore('settings',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function docs(){const db=await dbPromise;return new Promise((resolve,reject)=>{const r=db.transaction('documents').objectStore('documents').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function showDocs(){const list=await docs();byId('documentList').innerHTML=list.length?list.sort((a,b)=>b.added-a.added).map(d=>`<article class="document-item"><b>▱</b><div><strong>${d.name}</strong><p>${d.type||'ไม่ทราบประเภท'} · ${Math.ceil(d.size/1024).toLocaleString()} KB · เพิ่ม ${new Date(d.added).toLocaleDateString('th-TH')}</p></div><button data-delete-doc="${d.id}">ลบสำเนา</button></article>`).join(''):'<p class="muted">ยังไม่มีเอกสารในคลังเครื่องนี้</p>';document.querySelectorAll('[data-delete-doc]').forEach(b=>b.onclick=async()=>{const db=await dbPromise;db.transaction('documents','readwrite').objectStore('documents').delete(b.dataset.deleteDoc);toast('ลบสำเนาในคลังเครื่องนี้แล้ว');setTimeout(showDocs,100)})}
byId('filePicker').onchange=async e=>{const db=await dbPromise;const tx=db.transaction('documents','readwrite');for(const file of e.target.files)tx.objectStore('documents').put({id:crypto.randomUUID(),name:file.name,type:file.type,size:file.size,added:Date.now(),blob:file});tx.oncomplete=()=>{toast(`เก็บ ${e.target.files.length} ไฟล์ในเครื่องแล้ว`);showDocs()};e.target.value=''};
async function setting(key,value){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('settings','readwrite'),store=tx.objectStore('settings');if(typeof value!=='undefined')store.put({key,value});else {const r=store.get(key);r.onsuccess=()=>resolve(r.result?.value)}tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function updateFolderStatus(){const folder=await setting('document-folder');if(!folder)return;const permission=await folder.queryPermission({mode:'read'});byId('folderStatus').textContent=permission==='granted'?`เชื่อมโฟลเดอร์: ${folder.name} (เข้าถึงได้ในเบราว์เซอร์นี้)`: `โฟลเดอร์ ${folder.name} ต้องอนุญาตใหม่ก่อนใช้งาน`}
byId('chooseFolder').onclick=async()=>{if(!window.showDirectoryPicker){toast('เบราว์เซอร์นี้ไม่รองรับการเลือกโฟลเดอร์ — ใช้ Chrome หรือ Edge');return}try{const folder=await window.showDirectoryPicker({id:'condo-ledger-documents',mode:'readwrite'});await setting('document-folder',folder);await updateFolderStatus();toast(`เชื่อมโฟลเดอร์ ${folder.name} แล้ว`)}catch(error){if(error.name!=='AbortError')toast('ไม่สามารถเชื่อมโฟลเดอร์ได้')}};
byId('exportData').onclick=async()=>{const documentMetadata=(await docs()).map(({blob,...meta})=>meta);const backup={format:'condo-ledger-local-backup',version:1,exportedAt:new Date().toISOString(),properties:state.properties,transactions:state.transactions,documents:documentMetadata,notice:'Document file contents are intentionally not included. Keep the original documents in your PC folder.'};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));a.download=`condo-ledger-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('ดาวน์โหลดไฟล์สำรองข้อมูลแล้ว')};
showDocs();updateFolderStatus();render();
